const { Client } = require('pg');
const http = require('http');

const PG      = { host:'172.18.0.4', port:5432, database:'data_warehouse_gold', user:'nyanu', password:'nyanu', connectionTimeoutMillis:10000 };
const PROXY   = '172.18.0.8';
const PORT    = 3128;
const BASE    = '/BC260/api/etlpipeline/warehouse/v1.0';
const COMPANY = $vars.BC_COMPANY_ID || '00000000-0000-0000-0000-000000000000';
const ENTITY  = 'etlShipmentLines';
const NOW     = new Date().toISOString();

function bcReq(method, path, body) {
  return new Promise((resolve, reject) => {
    const pl = body ? JSON.stringify(body) : null;
    const req = http.request({
      hostname: PROXY, port: PORT,
      path: `${BASE}/companies(${COMPANY})/${path}`,
      method,
      headers: {
        'Content-Type': 'application/json', 'Accept': 'application/json',
        ...(pl ? { 'Content-Length': Buffer.byteLength(pl) } : {}),
        ...(method === 'PATCH' ? { 'If-Match': '*' } : {})
      }
    }, res => { let d=''; res.on('data',c=>d+=c); res.on('end',()=>resolve({status:res.statusCode,body:d})); });
    req.on('error', reject);
    if (pl) req.write(pl);
    req.end();
  });
}

// Compound key: documentNo + lineNo separated by '|'
async function upsert(documentNo, lineNo, data) {
  const r = await bcReq('POST', ENTITY, data);
  if (r.status === 201 || r.status === 200) return { action:'inserted', key:`${documentNo}|${lineNo}`, status:r.status };
  if (r.status === 409 || r.status === 422) {
    const filter = `documentNo eq '${encodeURIComponent(documentNo)}' and lineNo eq ${lineNo}`;
    const lookup = await bcReq('GET', `${ENTITY}?$filter=${filter}&$select=id`);
    let bcId = null;
    try { bcId = JSON.parse(lookup.body).value?.[0]?.id; } catch(e) {}
    if (bcId) {
      const r2 = await bcReq('PATCH', `${ENTITY}(${bcId})`, data);
      return { action:'updated', key:`${documentNo}|${lineNo}`, status:r2.status };
    }
    return { action:'error', key:`${documentNo}|${lineNo}`, status:409, detail:'record not found for PATCH' };
  }
  return { action:'error', key:`${documentNo}|${lineNo}`, status:r.status, detail:r.body.substring(0,200) };
}

const client = new Client(PG);
await client.connect();
const res = await client.query(`
  SELECT document_no, line_no, article_id, quantity, location_code
  FROM fact_shipment_lines
`);
await client.end();

const results = [];
for (const row of res.rows) {
  const r = await upsert(row.document_no, row.line_no, {
    documentNo: row.document_no||'',
    lineNo: parseInt(row.line_no)||0,
    articleId: row.article_id||'',
    quantity: parseFloat(row.quantity)||0,
    locationCode: row.location_code||'',
    etlLoadedAt: NOW
  });
  results.push(r);
}
const inserted = results.filter(r=>r.action==='inserted').length;
const updated  = results.filter(r=>r.action==='updated').length;
const errors   = results.filter(r=>r.action==='error').length;
console.log(`[WF-08E] fact_shipment_lines → BC: ${inserted} inserts | ${updated} updates | ${errors} errors`);
return [{ json: { table:'fact_shipment_lines', total:results.length, inserted, updated, errors } }];
